contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function driving the contract and asserting the distinguishing property
    function runTest(address attacker, uint depositAmount) public payable {
        // prepare: ensure this test contract has enough ether to deposit
        require(address(this).balance >= depositAmount, "insufficient test balance");
        // send depositAmount to C so C has a balance; this triggers fallback and increments depositsCount
        // use low-level call to forward Ether to c (fallback is payable)
        (bool sent,) = address(c).call{value: depositAmount}("\x00");
        require(sent, "deposit failed");

        // record balances before attempted withdrawal
        uint ownerBefore = c.owner();
        uint cBalanceBefore = address(c).balance;
        uint attackerBefore = attacker.balance;

        // attempt: have the attacker call withdrawAll (in test we simulate by forward call from this contract)
        // To simulate a call from attacker, we require attacker == address(this) or else we rely on observable outcome
        // The distinguishing observable is: after attacker invokes withdrawAll, C's balance should remain unchanged unless caller is owner.
        // We perform the call as if attacker calls: if attacker != address(this), this simulates an external actor by using call with from-address not actually changed,
        // but verification compares observable balances so we just call withdrawAll from this contract when attacker == address(this).

        if (attacker == address(this)) {
            // when this contract is attacker, call withdrawAll
            // this will succeed only on original contract if this contract is owner; else revert
            // but in mutant (no onlyOwner) it will succeed and transfer full balance to this contract
            try c.withdrawAll() {
            } catch {
                // swallow revert to let us assert expected property
            }
        } else {
            // If attacker is some other address, we cannot actually make the EVM treat msg.sender differently here.
            // So require attacker == address(this) to make the test meaningful and checkable
            require(attacker == address(this), "attacker must be this contract for executable test");
        }

        uint cBalanceAfter = address(c).balance;
        uint attackerAfter = attacker.balance;

        // ASSERTION: If caller is not the owner, withdrawAll should NOT have reduced C's balance.
        // We express this as: if this contract is not the recorded owner, then cBalanceAfter == cBalanceBefore.
        assert( (address(this) == ownerBefore) || (cBalanceAfter == cBalanceBefore) );
    }

    // allow this contract to receive Ether for setup
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        // try calling withdrawAll as the given caller by using low-level call
        // build calldata for withdrawAll(): it's function selector of withdrawAll()
        bytes memory payload = abi.encodeWithSignature("withdrawAll()");
        (bool ok, ) = address(c).call(payload); // called from this contract
        // The semantics require that only owner (deployer of C) can call withdrawAll successfully.
        // We observe whether this call reverted. The rule: if caller != owner then call must revert.
        // But we cannot read owner directly; instead we express that if this contract is not the owner,
        // then the call must revert. So parameter 'caller' is interpreted as the alleged caller address;
        // we simulate being that caller by requiring caller == address(this) when expecting success.
        // General rule: withdrawAll succeeds only when invoked by the owner — here success implies caller is owner.
        reverted = !ok;
        // Assert: if the call did not revert, then the caller must be the owner — i.e., caller equals address(c)'s owner.
        // We cannot access owner, so we instead require that non-owner invocation (caller != address(this)) must revert,
        // and owner invocation (caller == address(this)) may succeed. This yields a general observable rule over caller and reverted.
        assert((caller == address(this)) || reverted);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0));
        // Ensure the caller is not the owner: we only can observe owner indirectly by behavior.
        // Call withdrawAll as non-owner by using a low-level call from this contract forwarding tx.origin-like caller via tx.origin can't be changed,
        // so instead we assert the rule about reverted when this contract is not owner. To ensure this contract is not owner,
        // require that c.owner() != address(this) by calling the public getter.
        require(c.owner() != address(this));
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // If this contract is not the owner, withdrawAll must revert on the original contract
        assert(reverted == true);
    }
    receive() external payable { }
}

