pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to deposit and whether the owner's address is a reverting contract
    function testFuzz_property(uint128 depositAmount, bool ownerIsReverter) public {
        // keep depositAmount in a reasonable wide range but non-zero
        depositAmount = bound(depositAmount, 1, type(uint128).max);

        // Deploy either a normal EOA-simulating recipient or a reverter contract to act as owner
        address ownerAddr;
        Reverter rev;
        if (ownerIsReverter) {
            rev = new Reverter();
            ownerAddr = address(rev);
        } else {
            // use an EOA simulated by address(this) for simplicity
            ownerAddr = address(this);
        }

        // Fund the owner candidate so they can be set as msg.sender when creating new C is not possible.
        // But C was already deployed in setUp() with original deployer as owner; we need owner to be msg.sender for c.
        // So we must redeploy c from the chosen owner. Use vm.prank to deploy c from ownerAddr.
        // To deploy from ownerAddr if it's a contract (rev), we use vm.prank on that address; that works for both EOA and contract.
        vm.prank(ownerAddr);
        C localC = new C();
        c = localC;

        // Fund the contract so withdrawAll has balance to withdraw
        // give some Ether to a funding account and send to c via a deposit (fallback increments depositsCount)
        vm.deal(address(this), depositAmount);
        // send Ether to c via low-level call so fallback executes
        (bool s,) = address(c).call{value: depositAmount}("");
        require(s, "funding failed");

        // Now call withdrawAll as the owner (ownerAddr). This will either call withdraw(...) (reference)
        // or transfer directly (mutant). The difference is that if ownerAddr's receive/fallback reverts,
        // direct transfer will revert, while the reference's internal withdraw -> payable(msg.sender).transfer(...) also uses transfer,
        // but the mutation changed call path; to capture the behavioral difference we observe whether withdrawAll completes (ok)
        bool ok;
        vm.prank(ownerAddr);
        try c.withdrawAll{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General assertion: For the reference implementation, withdrawAll never reverts when called by the owner (ok == true)
        // because withdrawAll delegates to withdraw which transfers to msg.sender; however the mutant that transfers directly can
        // behave differently in presence of a reverting owner fallback; our adversarial Reverter makes the call revert.
        // This single assert reads c by observing whether the call succeeded (ok). The reference should always succeed here.
        assertTrue(ok);
    }
}

// adversarial helper: a contract whose fallback/receive reverts to simulate an owner that rejects Ether
contract Reverter {
    receive() external payable { revert("reject"); }
    fallback() external payable { revert("reject"); }
}

