pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameters: amount to deposit and whether caller is the adversarial contract
    function testFuzz_property(uint256 depositAmount, bool useReverter) public {
        // keep deposit amount within reasonable bounds and > 0
        depositAmount = bound(depositAmount, 1, 1 ether);

        // deploy an adversarial counterparty that reverts on receive
        Reverter rev = new Reverter();

        // choose actor: either the reverter contract or this EOA (address(this))
        address actor = useReverter ? address(rev) : address(this);

        // Fund the actor so it can send ETH to c
        vm.deal(actor, depositAmount);

        // Actor deposits into c via fallback (which is payable)
        if (actor == address(this)) {
            // call from this test contract
            (bool ok, ) = address(c).call{value: depositAmount}("");
            require(ok, "deposit failed");
        } else {
            // prank as the reverter contract to send funds (reverter has payable fallback that reverts only on receive?)
            // The Reverter's fallback will revert on receiving funds, so we cannot have it be the sender of deposit.
            // Instead, deploy a Sender helper to send funds when needed. We'll just have the test contract send
            // to c, but set msg.sender for withdrawal to be the reverter by calling withdrawAll via vm.prank.
            (bool ok, ) = address(c).call{value: depositAmount}("");
            require(ok, "deposit failed");
        }

        // Now call withdrawAll as the chosen actor. We want to observe whether withdrawAll reverts.
        bool ok;
        if (useReverter) {
            // when the caller is the reverter contract, its fallback/receive reverts on receiving ETH.
            // We impersonate the reverter to be msg.sender for withdrawAll.
            vm.prank(address(rev));
            try c.withdrawAll() {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            // normal EOA caller (this contract) should succeed
            vm.prank(address(this));
            try c.withdrawAll() {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // The universal property: for any depositAmount and choice, the reference contract's withdrawAll always succeeds (does not revert).
        assertTrue(ok);
    }
}

// Adversarial helper that reverts when receiving funds
contract Reverter {
    fallback() external payable {
        revert("I refuse funds");
    }
    receive() external payable {
        revert("I refuse funds");
    }
}

