pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: deposit amount and a flag whether the owner contract will revert on receive
    function testFuzz_property(uint256 depositAmount, bool ownerReverts) public {
        // keep depositAmount in a reasonable wide domain but not zero to ensure meaningful deposit
        depositAmount = bound(depositAmount, 1, type(uint128).max);

        // deploy an adversarial owner contract which may revert on receive
        AdversarialOwner adv = new AdversarialOwner(ownerReverts);

        // fund the adversarial owner so it can be the msg.sender when calling withdrawAll if needed
        vm.deal(address(adv), 1 ether);

        // make some other account deposit funds into c using fallback (fallback increments depositsCount but also accepts ether)
        address depositor = address(0xBEEF);
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        // deposit by sending Ether to c (fallback payable)
        (bool sent,) = address(c).call{value: depositAmount}("0x");
        require(sent, "deposit call failed in test setup");

        // Sanity: contract should have received the deposit
        assert(address(c).balance == depositAmount);

        // now set the contract owner to be the adversarial owner by impersonating the original owner
        // original owner is the test contract deployer (this test contract), so we need to have adv become owner
        // We cannot change C.owner after deployment; instead we will deploy a fresh C with adv as deployer to make adv owner
        // So recreate c with adv as deployer to ensure owner == adv
        c = C(address(new C()));
        // The above created c with this test as deployer; we must instead deploy a new C via adv to be owner.
        // Use low-level create by adv to deploy a new C with adv as msg.sender
        address payable deployed = payable(address(new Deployer().deploy()));
        // cast to C and replace c
        c = C(deployed);

        // now ensure contract has some balance: deposit into this new c
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        (bool sent2,) = address(c).call{value: depositAmount}("0x");
        require(sent2, "deposit call failed into new c");
        assert(address(c).balance == depositAmount);

        // Now have the adversarial owner call withdrawAll; use vm.prank to make adv the msg.sender
        vm.prank(address(adv));
        // adv will call c.withdrawAll; capture whether it reverts using try/catch pattern
        bool ok;
        try C(address(c)).withdrawAll{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The property: on the reference implementation, withdrawAll never reverts and empties the contract balance
        // We assert that withdrawAll returned (did not revert) OR, if it reverted, that the contract STILL has zero balance
        // To target the introduced mutant (direct transfer to msg.sender can revert on recipient revert), we check success and balance
        assertTrue(ok && address(c).balance == 0);
    }
}

// Helper that can be set to revert on receive (adversarial owner)
contract AdversarialOwner {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    receive() external payable {
        if (shouldRevert) revert("receive reverted");
    }
}

// Minimal deployer to ensure adv becomes owner of a newly deployed C via a call
contract Deployer {
    function deploy() external returns (address) {
        C c = new C();
        return address(c);
    }
}

