pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: amount to deposit and a flag to choose adversarial owner behavior
    function testFuzz_property(uint256 depositAmount, bool adversarial) public {
        // keep amounts reasonable for transfer semantics
        depositAmount = bound(depositAmount, 1, 1 ether);

        // deploy either a well-behaved recipient or a reverter recipient based on fuzz flag
        Recipient good = new RecipientAccept();
        Recipient bad = new RecipientRevert();
        Recipient ownerRecipient = adversarial ? bad : good;

        // fund the contract by calling fallback (payable) from an external depositor
        address depositor = address(0xBEEF);
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        (bool s, ) = address(c).call{value: depositAmount}("");
        require(s);

        // set the owner to be the recipient contract by deploying ownerContract and making owner call constructor-time
        // C's owner is set to deployer (this test contract). We need to simulate owner being the recipient contract.
        // We will instead perform the withdrawal as the current owner (this test contract) but make the to-address be the ownerRecipient
        // Achieve this by creating a ForwardingOwner that is a thin contract whose payable fallback forwards to ownerRecipient
        ForwardingOwner fo = new ForwardingOwner(address(ownerRecipient));

        // now we need to make c's owner equal to fo. The contract C sets owner at construction to msg.sender (this test),
        // so we cannot change owner; however we can impersonate owner by calling withdrawAll from the owner (this test) and
        // letting the mutant vs reference difference manifest in who receives the funds: both implementations send to msg.sender,
        // so we must call withdrawAll with msg.sender being the contract that will receive funds. Thus we call withdrawAll while
        // pranking as fo so that msg.sender inside C is fo and the transfer goes to fo.

        // fund the ForwardingOwner so it can receive funds (no-op, it's contract)
        // perform withdrawAll as fo
        vm.prank(address(fo));
        // Ensure fo has no code except the forwarding logic; call withdrawAll and capture success
        bool ok;
        try c.withdrawAll{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        // PROPERTY: After withdrawAll returns (i.e., call did not revert), the contract balance must be zero for the reference implementation.
        // We assert that address(c).balance == 0 when the call succeeded. This holds for the correct contract for all inputs.
        // The mutant can cause the call to revert or leave funds in the contract for some adversarial recipient; the fuzz will find that.
        if (ok) {
            assertTrue(address(c).balance == 0);
        } else {
            // If the call reverted, assertTrue should be on a fact the reference also would satisfy: however the reference never reverts
            // for a normal recipient; to keep a single assertTrue reading c and not assert on ok directly, we assert that either the call succeeded
            // and balance is zero, OR it failed (ok==false) which for the reference should not happen with the good recipient path; to keep single assert,
            // we assert that address(c).balance == 0 when ok is true, and if ok is false this will fail for the reference (so fuzz finds adversarial)
            assertTrue(address(c).balance == 0);
        }
    }
}

// Minimal recipient interface and implementations
abstract contract Recipient { receive() external payable virtual; }

contract RecipientAccept is Recipient { receive() external payable override { /* accept funds */ } }
contract RecipientRevert is Recipient { receive() external payable override { revert(); } }

// ForwardingOwner: when it receives Ether, it forwards it to the target recipient (but we will call withdrawAll with msg.sender=this contract,
// so payable transfer will send to this contract; its fallback just accepts (or can forward) depending on constructed target)
contract ForwardingOwner {
    address public target;
    constructor(address _t) { target = _t; }
    receive() external payable {
        // when receiving funds, try to forward to target; if target reverts, this receive will revert too (propagating behavior)
        (bool s, ) = target.call{value: msg.value}("");
        if (!s) revert();
    }
}

